function changesBetween(before,after){const out=[];for(const [key,value] of Object.entries(after)){if(Array.isArray(value)){for(const row of value){const old=(before[key]||[]).find(x=>x.id===row.id);if(JSON.stringify(old)!==JSON.stringify(row))out.push({key,id:row.id,value:row,before:old??null});}}else if(['presence','work'].includes(key)){for(const [id,row] of Object.entries(value)){if(JSON.stringify(before[key]?.[id])!==JSON.stringify(row))out.push({key,id,value:row,before:before[key]?.[id]??null});}}}return out;}
function syncLabel(text){document.querySelector('.savestate').textContent=text;}
function persist(){if(leaving)return;clearTimeout(syncTimer);if(syncFailed){syncLabel(pendingConflict?'● Choose conflicting field values':'● Changes retained — reconnecting');return;}syncLabel('● Saving changes…');syncTimer=setTimeout(flush,300);}
function retrySave(delay){clearTimeout(retryTimer);retryTimer=setTimeout(()=>{if(leaving)return;if(signingOut){retrySave(5000);return;}if(pendingConflict)return;syncFailed=false;flush();},delay);}
function saveWarning(message,canRetry=true){const box=$('#storagewarning');box.hidden=false;box.innerHTML='<strong>'+esc(message)+'</strong> '+(canRetry?'<button id="retrySave" class="secondary smallbtn">Retry now</button> ':'')+'<button id="downloadUnsaved" class="secondary smallbtn">Download a copy</button>';if(canRetry)$('#retrySave').onclick=()=>{clearTimeout(retryTimer);syncFailed=false;flush();};$('#downloadUnsaved').onclick=()=>downloadBlob(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'gryn-unsaved-work.json');}
function conflictWarning(data){pendingConflict=data;const box=$('#storagewarning');box.hidden=false;const preview=v=>typeof v==='object'?'Updated document/list details':String(v??'(empty)').slice(0,160);box.innerHTML='<strong>Two people changed the same field.</strong><p>Your entries and selected files are retained. Choose the value to keep for each field; other changes merge automatically.</p>'+data.conflicts.map((c,i)=>'<label>'+esc(c.key+' · '+(c.path.join(' / ')||'record'))+'<select data-conflict="'+i+'"><option value="">Choose…</option><option value="local">My value: '+esc(preview(c.local))+'</option><option value="shared">Shared value: '+esc(preview(c.shared))+'</option></select></label>').join('')+'<button id="resolveSync" class="secondary">Apply choices and save</button> <button id="recheckSync" class="secondary">Recheck shared changes</button>';$('#recheckSync').onclick=()=>{pendingConflict=null;syncFailed=false;flush();};$('#resolveSync').onclick=()=>{const choices=[...box.querySelectorAll('[data-conflict]')].map(n=>n.value);if(choices.some(v=>!v))return toast('Choose a value for each conflicting field.');const edits=changesBetween(baseline,state),result=rebaseChanges(data.state,edits,(c,path)=>{const i=data.conflicts.findIndex(x=>x.key===c.key&&x.id===c.id&&JSON.stringify(x.path)===JSON.stringify(path));return i<0?undefined:choices[i];});if(result.conflicts.length)return toast('Additional fields changed while resolving. Retry saving to review them.');state=applyChanges(data.state,result.changes);baseline=structuredClone(data.state);revision=data.version;pendingConflict=null;syncFailed=false;box.hidden=true;flush();};syncLabel('● Review conflicting field values');}
