async function submit(form,submitter){const d=Object.fromEntries(new FormData(form)),kind=form.dataset.form,id=form.dataset.id,before=structuredClone(state);if(kind==='visa'&&route!=='visa')throw Error('Submit visas from the Visa menu only.');if(submitter?.hasAttribute('data-submit-case')){if(kind==='app'&&appBy(id)?.visaId)throw Error('Use the linked Visa form to update this case.');d.status=kind==='visa'?'Visa Submitted':'Application submitted';}if(blocked())throw Error('Work access is restricted.');let keepDialog=false;try{if(kind==='chooseStudent'){extraApplicationDialog(d.leadId);return;}if(kind==='multiApplication'){await flush();if(syncFailed)throw Error('Resolve unsaved changes first.');const r=await fetch('/api/gryn/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...d,action:'addStudentApplication',leadId:id})}),result=await r.json();if(!r.ok)throw Error(result.error);const newApp=result.state.applications.find(a=>a.leadId===id&&!state.applications.some(old=>old.id===a.id));state=result.state;baseline=structuredClone(state);revision=result.version;$('#dialog').close();go('applications');appDialog(newApp.id);return;}if(kind==='directVisa'||kind==='directApplication'){await flush();if(syncFailed)throw Error('Resolve unsaved changes first.');const r=await fetch('/api/gryn/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...d,action:'createCase',caseType:kind==='directVisa'?'visa':'application'})}),result=await r.json();if(!r.ok)throw Error(result.error);state=result.state;baseline=structuredClone(state);revision=result.version;const lead=state.leads.find(l=>!before.leads.some(old=>old.id===l.id));if(!lead)throw Error('Case created. Refresh the register to open it.');$('#dialog').close();go(kind==='directVisa'?'visa':'applications');return kind==='directVisa'?visaDialog(appBy(lead.applicationId).visaId):appDialog(lead.applicationId);}if(kind==='daily'){const tasks=d.tasks.split('\n').map(t=>t.trim()).filter(Boolean);if(!tasks.length)throw Error('Enter at least one task.');tasks.forEach(text=>state.tasks.push({id:makeId(),staffId:actor,day:taskDay(),text,done:false}));audit(state,actor,'Entered daily work plan');lastTaskReminder=Date.now();}else if(kind==='addTask'){if(!d.text.trim())throw Error('Enter a task');state.tasks.push({id:makeId(),staffId:actor,day:taskDay(),text:d.text.trim(),done:false});}else if(kind==='lead'){let l;if(id)l=updateLead(state,actor,id,d);else{l=createLead(state,actor,d);l.relationshipId=d.relationshipId||l.relationshipId;}if(d.staffNotes!==undefined)l.staffNotes=d.staffNotes;if(!id&&!isLeadership()&&d.notes)l.notes=d.notes;}else if(kind==='app'){const a=appBy(id),l=leadOf(a);requireEdit(state,actor,'applications',l);a.refusalHistory=d.refusalHistory||'';a.refusalDetails=d.refusalDetails||'';a.refusalDeclaration=!!d.refusalDeclaration;if(d.status==='Application submitted'&&(!a.refusalDeclaration||!['Yes','No'].includes(a.refusalHistory)))throw Error('Record visa refusal history and tick the declaration before submitting.');const files=[...form.querySelector('input[type="file"]').files];const removed=a.documents.filter(doc=>d['remove-'+doc.id]);a.documents=a.documents.filter(doc=>!d['remove-'+doc.id]);if(removed.length)audit(state,actor,'Removed '+removed.length+' application document(s)',id);const previousCount=a.documents.length;await storeDocs(files,a.documents);a.documents.slice(previousCount).forEach((doc,i)=>doc.category=form.querySelector(`[name="upload-${i}"]`)?.value||'Other');for(const doc of a.documents.slice(0,previousCount))doc.category=d['existing-'+doc.id]||doc.category;a.program=d.program||'';a.topUpQualification=d.topUpQualification||'';a.incompleteDocumentsNote=d.incompleteDocumentsNote||'';a.englishRequired=d.englishRequired||'Not confirmed';a.manualRank=d.manualRank||'';a.manualNotes=d.manualNotes||'';if(!a.visaId&&d.status==='Application submitted')validateSubmission(a);if(!a.visaId)appStatus(state,actor,id,d.status);for(const key of ['school','course','country','intake','intakeYear','passportNumber','applicationNotes'])a[key]=d[key]||'';a.lastWorkedAt=new Date().toISOString();l.attendedAt=a.lastWorkedAt;audit(state,actor,'Saved Application details',id);}else if(kind==='visa'){const v=state.visas.find(v=>v.id===id);requireEdit(state,actor,'visa',leadBy(v.leadId));if(d.status==='Visa Submitted'&&v.status!==d.status)assertVisaSubmission(state,actor,v);await storeDocs([...form.querySelector('input[type="file"]').files],v.documents);for(const [i,doc] of v.documents.entries())doc.category=d['existing-'+doc.id]||form.querySelector(`[name="upload-${i-(v.documents.length-form.querySelector('input[type=file]').files.length)}"]`)?.value||doc.category;visaStatus(state,actor,id,d.status);for(const key of ['type','passport','travelDate','appointmentDate','reference','notes'])v[key]=d[key]||'';if(d.assigneeId){if(!['Owner','Operations','Relationship Management'].includes(me().accessRole))throw Error('Only leadership or Relationship Management assigns Visa tasks.');if(me().accessRole==='Relationship Management'&&d.assigneeId!==actor&&who(state,d.assigneeId)?.managerId!==actor)throw Error('Assign to a member of your team.');v.assigneeId=d.assigneeId;}}else if(kind==='handoff'){const l=leadBy(id);requireEdit(state,actor,'leads',l);if(who(state,d.managerId)?.accessRole!=='Relationship Management')throw Error('Select a Relationship Manager.');l.relationshipId=d.managerId;l.staffId=d.managerId;audit(state,actor,'Handed lead to Relationship Manager',id);}else if(kind==='newPayment'){const a=appBy(d.appId),l=leadOf(a);requireEdit(state,actor,'payments',l);if(d.origin==='visa'&&!a.visaId)throw Error('This Application has not reached Visa yet.');const p={id:makeId(),appId:a.id,origin:d.origin,amount:0,currency:'NGN',type:'Service charges',staffId:l.staffId,status:'Awaiting details',createdAt:new Date().toISOString()};state.payments.unshift(p);persist();render();paymentDialog(p.id);return;}else if(kind==='payment'){const payment=savePayment(state,actor,id,d);payment.documents??=[];const priorCount=payment.documents.length;await storeDocs([...form.querySelector('input[type="file"]').files],payment.documents);for(const [i,doc] of payment.documents.entries())doc.category=d['existing-'+doc.id]||(i>=priorCount?form.querySelector(`[name="upload-${i-priorCount}"]`)?.value||'Payment receipt':doc.category);}else if(kind==='voucher'){if(isHR())d.category='Staff';const v=createVoucher(state,actor,d);v.documents=[];await storeDocs([...form.elements.files.files],v.documents);}else if(kind==='payroll'){mustFinance();const gross=minor(d.gross),deductions=minor(d.deductions);if(!gross||deductions>=gross)throw Error('Gross pay must exceed deductions.');const staff=who(state,d.staffId);if(!staff)throw Error('Choose staff.');const net=gross-deductions,v=createVoucher(state,actor,{description:'Payroll '+d.month,payee:staff.name,category:'Staff',staffId:staff.id,amount:(net/100).toFixed(2),currency:d.currency,date:d.date});state.payslips.unshift({id:makeId(),staffId:staff.id,month:d.month,gross,deductions,net,currency:d.currency,notes:d.notes,voucherId:v.id});audit(state,actor,'Created staff payslip',v.id);}else if(kind==='invoice'){mustFinance();if(isHR())throw Error('HR has staff-finance access only.');createInvoice(state,actor,d);}else if(kind==='budget'){mustFinance();state.budgets.push({id:makeId(),...d,category:isHR()?'Staff':d.category,amountMinor:minor(d.amount)});audit(state,actor,'Created monthly budget');}else if(kind==='menuLimits'){setMenuRestrictions(state,actor,id,new FormData(form).getAll('disabledMenus'));}else if(kind==='role'){setRole(state,actor,id,d.role);}else if(kind==='staff'){if(!['Owner','Operations','Management'].includes(me().accessRole))throw Error('Staff management access required.');let u=who(state,id);if(u&&!mayControl(u)&&u.id!==actor&&me().accessRole!=='Owner')throw Error('Cannot edit this staff profile.');if(!d.name.trim())throw Error('Name is required.');if(!u){u={id:makeId(),accessRole:'Admission Team',sessionVersion:0};state.staff.push(u);}for(const key of ['name','email','role','managerId','duties'])u[key]=d[key]||'';u.leadTarget=Number(d.leadTarget||0);u.appTarget=Number(d.appTarget||0);audit(state,actor,'Updated staff profile',u.id);}else if(kind==='query'||kind==='appraisal'){const target=who(state,d.staffId);if(!target||!mayControl(target))throw Error('This role cannot query or appraise that staff profile.');state[kind==='query'?'queries':'appraisals'].unshift({id:makeId(),...d,createdBy:actor,createdAt:new Date().toISOString()});audit(state,actor,kind==='query'?'Issued staff query':'Created staff appraisal',d.staffId);}else if(kind==='respondQuery'){const query=state.queries.find(q=>q.id===id&&q.staffId===actor);if(!query)throw Error('Query not assigned to you.');query.response=d.response;audit(state,actor,'Responded to staff query',id);}else if(kind==='chat'){const target=isLeadership()?d.staffId:(state.staff.find(u=>u.id===me().managerId&&!u.frozen)?.id||state.staff.find(u=>['Operations','Owner'].includes(u.accessRole)&&!u.frozen)?.id);if(!target)throw Error('No manager is available. Please contact Operations.');if(isLeadership()){if(!who(state,target))throw Error('Select recipient');state.messages.push({id:makeId(),staffId:target,from:actor,body:d.body,createdAt:new Date().toISOString()});}else{state.chats.push({id:makeId(),staffId:actor,from:actor,to:target,direction:'out',body:d.body,createdAt:new Date().toISOString()});}audit(state,actor,'Sent team feedback');}else if(kind==='announcement'){if(!isLeadership())throw Error('Leadership required');if(!d.body.trim())throw Error('Enter the announcement');const recipients=state.staff.filter(u=>u.id!==actor).map(u=>u.id);state.notices.unshift({id:makeId(),...d,from:actor,recipientIds:recipients,acknowledgedBy:[],mandatory:me().accessRole==='Owner',createdAt:new Date().toISOString()});audit(state,actor,'Published team announcement');}else if(kind==='issue'){state.issues.push({id:makeId(),staffId:actor,...d,createdAt:new Date().toISOString()});audit(state,actor,'Logged unresolved issue');}persist();stagedFiles=[];await flush();if(syncFailed)return toast('Changes are not saved yet. Resolve the sync error shown above.');$('#dialog').close();render();toast('Saved to the shared workspace.');}catch(err){for(const fileId of stagedFiles)try{await fileStore('delete',fileId)}catch{}stagedFiles=[];state=before;throw err}}
// Delegation keeps every interaction attached after rendering.
document.addEventListener('click',async e=>{const b=e.target.closest('[data-act],[data-route],[data-sub],[data-monitor]');if(!b)return;try{if(b.dataset.route)return go(b.dataset.route);if(b.dataset.sub){sub=b.dataset.sub;return render()}if(b.dataset.monitor){monitorMode=b.dataset.monitor;return render()}await act(b.dataset.act,b.dataset.id)}catch(err){formError(err)}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const submitButtons=[...form.querySelectorAll('button[type="submit"]')];submitButtons.forEach(b=>b.disabled=true);try{await submit(form,e.submitter);if(!syncFailed)formNav.saved(form)}catch(err){formError(err)}finally{submitButtons.forEach(b=>b.disabled=false)}});
document.addEventListener('input',e=>{if(e.target.id==='search'){q=e.target.value;refreshResults()}});
function refreshResults(){if(!$('#results'))return;if(route==='leads')$('#results').innerHTML=leadTable(filterLeads(scoped(state,actor)).filter(l=>!statusFilter||leadStatus(state,l)===statusFilter));if(route==='applications')$('#results').innerHTML=appTable(state.applications.filter(a=>isApplication(a)&&visibleLead(state,actor,leadOf(a))&&filterLeads([{...leadOf(a),school:a.school||leadOf(a).school,course:a.course||leadOf(a).course,country:a.country||leadOf(a).country}]).length&&(!statusFilter||a.status===statusFilter)));if(route==='visa')$('#results').innerHTML=visaTable(state.visas.filter(v=>visibleLead(state,actor,leadBy(v.leadId))&&filterLeads([leadBy(v.leadId)]).length&&(!statusFilter||v.status===statusFilter)&&(['Owner','Operations','Relationship Management'].includes(me().accessRole)||v.assigneeId===actor)));}
document.addEventListener('change',e=>{try{if(e.target.id==='actor'){const next=e.target.value;e.target.disabled=true;flush().then(async()=>{if(syncFailed)throw Error('Save pending changes before switching platforms.');const response=await fetch('/api/gryn/switch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor:next})});if(!response.ok)throw Error((await response.json()).error);location.reload();}).catch(err=>toast(err.message));return;}if(e.target.id==='statusFilter'){statusFilter=e.target.value;return refreshResults()}if(e.target.id==='ownerFilter'){ownerFilter=e.target.value;return refreshResults()}if(e.target.dataset.report){reportCfg[e.target.dataset.report]=e.target.value;return render()}if(e.target.id==='financeCurrency'){financeCurrency=e.target.value;return render()}if(e.target.id==='financeMonth'){financeMonth=e.target.value;return render()}if(e.target.dataset.task){const t=state.tasks.find(t=>t.id===e.target.dataset.task&&t.staffId===actor);if(t){t.done=e.target.checked;audit(state,actor,t.done?'Completed daily task':'Reopened daily task',t.id);persist();render();}}}catch(err){toast(err.message)}});
$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#closedialog').onclick=()=>formNav.discardClose();$('#pausealerts').onclick=()=>{const b=$('#alertbar');b.classList.toggle('paused');$('#pausealerts').textContent=b.classList.contains('paused')?'▶':'Ⅱ'};
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next!==route)go(next)});
const personal=installPersonalWorkspace({state:()=>state,actor:()=>actor,go,dialog,render,toast,flush,failed:()=>syncFailed,apply:d=>{state=d.state;baseline=structuredClone(state);revision=d.version;render();}});
const formNav=installFormNavigation({actor:()=>actor,route:()=>route,go});
let updates;const addon=createEnhancements({state:()=>state,actor:()=>actor,flush,failed:()=>syncFailed,apply:data=>{state=data.state;baseline=structuredClone(state);revision=data.version;fromStorage=true;render();fromStorage=false;},toast,go,dialog,notify:list=>updates?.notify(list)});const ops=createOperations({state:()=>state,actor:()=>actor,flush,failed:()=>syncFailed,apply:data=>{state=data.state;baseline=structuredClone(state);revision=data.version;fromStorage=true;render();fromStorage=false;},toast,go,dialog,render,timeFor});function chatView(){return ops.chat()+addon.inbox();}
updates=installWorkspaceUpdates({state:()=>state,actor:()=>actor,flush,failed:()=>syncFailed,apply:data=>{state=data.state;baseline=structuredClone(state);revision=data.version;render();},toast,go,dialog,open:act,thread:id=>addon.openThread(id)});
const ticker=setInterval(()=>{if($('#headerTime'))$('#headerTime').textContent=new Date().toLocaleString();document.querySelectorAll('[data-clock]').forEach(n=>n.textContent=timeFor(n.dataset.clockActor||actor));if(Date.now()-lastTaskReminder>=30*60000){const unfinished=state.tasks.filter(t=>t.staffId===actor&&t.day===taskDay()&&!t.done);if(unfinished.length){toast(unfinished.length+' daily tasks are still pending. Open Daily tasks to review.');alerts();}lastTaskReminder=Date.now();}},1000);ticker.unref?.();const heartbeat=setInterval(()=>{if(!signingOut&&!blocked()){if(!$('#dialog').open&&!formNav.hasDrafts())recordPresence();alerts()}},60000);heartbeat.unref?.();persist();render();

function performancePanel(){const d=dashboardSummary(state,dashboardPeriod,dashboardDate);const groups=[['Countries most applied to',d.countries,false],['Universities most applied to',d.universities,false],['Top performing staff',d.staff,true],['Top performing agents',d.agents,true]];return panel('Application insights',`<div class="inline-actions"><label>Period <select id="dashboardPeriod">${[['day','Day'],['week','Week'],['month','Month'],['year','Year']].map(([v,l])=>`<option value="${v}" ${v===dashboardPeriod?'selected':''}>${l}</option>`).join('')}</select></label><label>Date in period <input id="dashboardDate" type="date" value="${dashboardDate}"></label></div><p class="hint">${esc(d.label)} · Lagos time · ${d.total} applications created in this period. Includes only records you can access. Each application counts separately, including multiple applications for one student.</p><p class="hint">Performance ranks current outcomes for these applications: enrolled, then offers, then submissions, then case count. Staff credit uses the current admission officer (or assigned staff); agents use the recorded referral. This is a case-outcome summary, not an individual effort score.</p><div class="staff-performance">${groups.map(([title,rows,performance])=>{const max=Math.max(1,...rows.map(r=>r.count));return `<section><h3>${title}</h3>${rows.map((r,i)=>`<div><strong>${i+1}. ${esc(r.name)}</strong><small> · ${r.count} application${r.count===1?'':'s'}${performance?` · ${r.enrolled} enrolled · ${r.offers} offers · ${r.submitted} submitted`:''}</small><div class="performance-bar" title="${r.count} applications"><i style="width:${Math.round(r.count/max*100)}%"></i></div></div>`).join('')||empty('No applications in this period.')}</section>`;}).join('')}</div>`);}
document.addEventListener('change',e=>{if(e.target.id==='dashboardPeriod'){dashboardPeriod=e.target.value;render();}if(e.target.id==='dashboardDate'&&e.target.value){dashboardDate=e.target.value;render();}});


document.querySelector('#signout').onclick=async()=>{if(signingOut)return;if(formNav.hasDrafts()&&!confirm('You have unfinished forms. Sign out and discard these temporary drafts?'))return;const button=$('#signout');signingOut=true;button.disabled=true;clearTimeout(syncTimer);try{await flush();if(syncFailed){if(!confirm('Some changes could not be saved. Download a copy of your unsaved work and sign out now?'))return;downloadBlob(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'gryn-unsaved-work.json');}await requestSignOut('/api/gryn/logout');leaving=true;clearTimeout(retryTimer);clearTimeout(syncTimer);clearInterval(ticker);clearInterval(heartbeat);formNav.reset();location.replace('/index.html');}catch(err){toast(err.name==='TimeoutError'?'Sign out timed out. Check your connection and retry.':err.message);}finally{if(!leaving){signingOut=false;button.disabled=false;if(!syncFailed&&changesBetween(baseline,state).length)persist();}}};

function marketingLinkPanel(){return `<p class="hint">Share this public form in a social media bio, campaign or website button. New enquiries enter Leads, with automatic marketing assignment. No CRM login is needed.</p><div class="formgrid"><label>Marketing channel<select id="marketingSource">${selectOptions(['Website','WhatsApp','Facebook','Instagram','TikTok','LinkedIn','X'],'Website')}</select></label><label>Campaign name (optional)<input id="marketingCampaign" maxlength="120" placeholder="e.g. September intake"></label></div><label>Shareable link<input id="marketingUrl" readonly value="${esc(location.origin+'/enquire.html?utm_source=Website')}" style="width:100%"></label><div class="inline-actions">${button('Copy link','copyMarketingLink')}<a id="marketingPreview" href="/enquire.html?utm_source=Website" target="_blank" rel="noopener">Preview form ↗</a></div>`;}
document.addEventListener('input',e=>{if(!['marketingSource','marketingCampaign'].includes(e.target.id))return;const url=new URL('/enquire.html',location.origin);url.searchParams.set('utm_source',$('#marketingSource').value);if($('#marketingCampaign').value.trim())url.searchParams.set('utm_campaign',$('#marketingCampaign').value.trim());$('#marketingUrl').value=url.href;$('#marketingPreview').href=url.href;});

function applicationChecklist(a){return `<section class="info"><strong>Supporting documents</strong><p>Documents are optional for submission. Select files to upload with Save changes or Submit application; you can add further documents later. WAEC / NECO PIN is optional for postgraduate programmes.</p>${(a.documents||[]).map(d=>`<div>📎 ${esc(d.name)} — ${esc(d.category||'Other')}</div>`).join('')}</section>`;}
function refreshApplicationChecklist(f){if(!f?.matches('[data-form="app"]'))return;syncTopUpRoute(f);const a=appBy(f.dataset.id),d=Object.fromEntries(new FormData(f));const docs=a.documents.filter(x=>!d['remove-'+x.id]).map(x=>({...x,category:d['existing-'+x.id]||x.category}));[...f.elements.files.files].forEach((file,i)=>docs.push({id:'pending-'+i,category:f.querySelector(`[name="upload-${i}"]`)?.value||'Other'}));const next={...a,program:d.program,topUpQualification:d.topUpQualification,englishRequired:d.englishRequired,documents:docs};const el=$('#applicationChecklist');if(el)el.innerHTML=applicationChecklist(next);}
document.addEventListener('change',e=>{const f=e.target.closest('[data-form="app"]');if(f)refreshApplicationChecklist(f);});
installDocumentPicker({categories:DOC_CATEGORIES,onChange:refreshApplicationChecklist});

function syncTopUpRoute(root){const program=root?.querySelector('[name="program"]'),routeField=root?.querySelector('[name="topUpQualification"]');if(!program||!routeField)return;const show=program.value==='Top-Up';routeField.closest('.field').style.display=show?'':'none';routeField.disabled=!show;}



document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='resetAccountPassword')return;e.preventDefault();const b=e.submitter;b.disabled=true;try{const payload=Object.fromEntries(new FormData(f));if(payload.password!==payload.confirmPassword)throw Error('The new passwords do not match.');const r=await fetch('/api/gryn/password-reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok)throw Error(d.error);f.reset();$('#dialog').close();if(d.signedOut){alert('Password changed. Sign in again using the new password.');location.reload();return;}toast('Password reset. The account must sign in with the new password.');}catch(err){$('#resetPasswordError').textContent=err.message;}finally{b.disabled=false;}});


document.addEventListener('gii-open-thread',e=>{if(state.conversations?.some(c=>c.id===e.detail?.id))addon.openThread(e.detail.id);});
